"""Command-line interface for regional sales reports."""

import argparse
import sys

from saleskit.summary import summarize


def format_report(totals):
    """Render region totals as one line each: name, units, revenue .2f."""
    return "\n".join(
        f"{region} {values['units']} {values['revenue']:.2f}"
        for region, values in totals.items()
    )


def build_parser():
    parser = argparse.ArgumentParser(prog="saleskit.cli")
    subparsers = parser.add_subparsers(dest="command", required=True)
    report = subparsers.add_parser("report", help="Print a regional sales report")
    report.add_argument("path", help="Path to a UTF-8 sales CSV")
    return parser


def main(argv=None):
    parser = build_parser()
    args = parser.parse_args(argv)
    if args.command == "report":
        print(format_report(summarize(args.path)))
        return 0
    parser.error(f"unknown command: {args.command}")


if __name__ == "__main__":
    sys.exit(main())
